INSERT IGNORE INTO `gov24_public_service` (`service_id`, `support_type`, `service_name`, `service_purpose_summary`, `support_target`, `selection_criteria`, `support_content`, `application_method`, `application_deadline`, `detail_url`, `organization_code`, `organization_name`, `department_name`, `view_count`, `organization_type`, `user_type`, `service_category`, `reception_agency`, `contact_phone`, `source_registered_at`, `source_updated_at`, `synced_at`, `created_at`, `updated_at`) VALUES ('305000000130','서비스(의료)','취약계층 반려동물 의료비 지원','관내 수급자, 차상위계층, 한부모가족 반려동물 의료비 지원','관내 주민등록을 두고 개와 고양이를 기르는 기초생활수급자, 차상위계층 및 한부모가족(가구당 2마리 까지 신청 가능)',NULL,'지원대상 : 관내 주민등록을 두고 개와 고양이를 기르는 기초생활수급자, 차상위계층 및 한부모가족(가구당 2마리까지 신청 가능)\r\n\r\n사업기간 : ~ 예산소진시까지\r\n\r\n신청방법 : 동물등록자 본인이 반려동물과 함께 준비서류를 준비하여 관내 지정 동물병원에 방문하여 신청\r\n *준비서류 : 신분증, 취약계층 증빙서류(수급자 증명서, 차상위계층, 한부모가족 확인서)-3개월이내 발급/ 반려견,반려묘의 경우 동물등록증\r\n\r\n\r\n\r\n지원내용\r\n \r\n 1. 필수진료 : 반려동물 필수 동물의료지원(정해진 진료 항목만 지원가능)\r\n   - 기초건강검진, 필수예방접종, 심장사상충 예방약\r\n   - 마리당 20만원 이내 지원, 보호자 1만원 부담\r\n 2. 선택진료 : 필수진료 후 추가 진료 요청시 지원\r\n   - 기초검진과정 중 발견된 증상, 질병에 대해 치료 또는 중성화 수술\r\n   - 진료 후 치료가 필요한 진료 항목만을 지원하며, 미용, 심장사상충 예방약, 영양제 등 단순 처방은 제외\r\n   - 마리당 20만원 이내 지원(초과하는 진료비는 보호자 부담)','방문신청','~예산소진시까지','https://www.gov.kr/portal/rcvfvrSvc/dtlEx/305000000130','3050000','서울특별시 동대문구','보건위생과',3170,'시군구','가구','행정·안전',NULL,'동대문구보건소/02-2127-4273','2022-05-30 16:23:18','2026-08-14 09:49:07','2026-08-17 19:00:36','2026-08-05 04:17:30','2026-08-17 19:00:36');
INSERT IGNORE INTO `gov24_public_service` (`service_id`, `support_type`, `service_name`, `service_purpose_summary`, `support_target`, `selection_criteria`, `support_content`, `application_method`, `application_deadline`, `detail_url`, `organization_code`, `organization_name`, `department_name`, `view_count`, `organization_type`, `user_type`, `service_category`, `reception_agency`, `contact_phone`, `source_registered_at`, `source_updated_at`, `synced_at`, `created_at`, `updated_at`) VALUES ('305000000132','현금','동대문구 유기동물 입양비 지원','관내 유실,유기동물을 반려 목적의 입양 후 소요된 소유자 부담 비용 지원/1마리당 25만원','우리 구 유실 유기동물(개,고양이)를 구 지정 동물보호센터에서 반려 목적으로 입양하려는 자로써 동물등록 완료 입양자\r\n  - 유기돔물 입양 후 6개월 이내 신청 건에 한하여 지급',NULL,'1. 지원대상 : 우리 구 보호중인 유기동물을 반려 목적으로 입양하려는 자로써 동물등록 완료 입양자\r\n  - 유기돔물 입양 후 6개월 이내 신청 건에 한하여 지급\r\n2. 신청방법 : 입양자 본인이 유기동물 입양관련 비용 지출 후 서류 준비하여 신청(방문, 이메일) 검토 후 지급\r\n  - 준비서류 : 입양비 신청서, 입양자 신분증, 입양확인서 사본, 등물등록증 사본, 입양비 지출 관련 증빙서류(지출영수증, 병원진료내역서, 기타 입양관련 지출내역 등)\r\n                      입양자 본인명의 통장사본\r\n3. 지원내용 : 질병질단비, 치료비, 예방접종, 중성화수술비, 내장형 동물 등록비, 미용비, 펫보험 가입비(신청일 기준 유효한 것) \r\n                      중 입양 시 지출한 비용 중 마리당 최대     25     만원까지 지원','방문신청','상시신청','https://www.gov.kr/portal/rcvfvrSvc/dtlEx/305000000132','3050000','서울특별시 동대문구','보건위생과',1399,'시군구','개인','행정·안전',NULL,'동대문구보건소 보건위생과/02-2127-4273','2022-05-30 17:25:14','2026-08-14 09:47:23','2026-08-17 19:00:37','2026-08-05 04:17:32','2026-08-17 19:00:37');
INSERT IGNORE INTO `gov24_public_service` (`service_id`, `support_type`, `service_name`, `service_purpose_summary`, `support_target`, `selection_criteria`, `support_content`, `application_method`, `application_deadline`, `detail_url`, `organization_code`, `organization_name`, `department_name`, `view_count`, `organization_type`, `user_type`, `service_category`, `reception_agency`, `contact_phone`, `source_registered_at`, `source_updated_at`, `synced_at`, `created_at`, `updated_at`) VALUES ('305000000167','기타(교육)||서비스(일자리)','반려동물 전문인력 양성사업','반려동물 관련 취업을 희망하는 구민에게 취업 전문 교육 및 취업연계','반려동물 관련 취업을 희망하는 동대문구 구민',NULL,'반려동물 관련 취업을 희망하는 구민에게 취업 전문 교육 및 취업연계','정부24온라인신청||기타 온라인신청','2025.08.06~2025.09.05','https://www.gov.kr/portal/rcvfvrSvc/dtlEx/305000000167','3050000','서울특별시 동대문구','청년정책고용과',741,'시군구','개인','고용·창업',NULL,'청년정책고용과/02-2127-4974','2022-10-31 10:25:11','2026-08-14 09:44:54','2026-08-17 19:00:36','2026-08-05 04:17:30','2026-08-17 19:00:36');
