INSERT IGNORE INTO `gov24_public_service` (`service_id`, `support_type`, `service_name`, `service_purpose_summary`, `support_target`, `selection_criteria`, `support_content`, `application_method`, `application_deadline`, `detail_url`, `organization_code`, `organization_name`, `department_name`, `view_count`, `organization_type`, `user_type`, `service_category`, `reception_agency`, `contact_phone`, `source_registered_at`, `source_updated_at`, `synced_at`, `created_at`, `updated_at`) VALUES ('318000000432','현금','유실·유기동물 입양비 지원','영등포구 지정 동물보호센터의 유실·유기동물 입양시 소유자 부담비용 지원(최대 15만원)','영등포구 지정 동물보호센터에서 유실·유기동물을 반려의 목적으로 입양하려는 자로서 아래의 조건을 모두 충족하는 자\r\n- 동물등록(내장형) 완료\r\n- 동물사랑배움터(apms.epis.or.kr) \'입양예정자 교육\'을 입양 전(또는 입양비 신청 전)에 이수한 자\r\n- 입양 후 1년이 경과하지 아니한 자\r\n\r\n※ 영등포구 지정 동물보호센터: (사)한국동물구조관리협회',NULL,'영등포구 지정 동물보호센터의 유실·유기동물 입양시 소유자 부담비용 지원\r\n- 소유자 부담비용의 60%, 최대 15만원 지원\r\n- 지원범위: 질병진단비, 치료비, 예방접종, 중성화수술비, 내장형 동물등록비, 미용비, 펫보험 가입비(신청일 기준 유효한 보험에 한함), 사회화교육 및 훈련비','직접입력','입양 후 1년 이내. 예산 소진시까지','https://www.gov.kr/portal/rcvfvrSvc/dtlEx/318000000432','3180000','서울특별시 영등포구','생활건강과',117,'시군구','개인','생활안정',NULL,'영등포구보건소 생활건강과/02-2670-4720','2025-12-24 14:13:06','2026-08-05 14:52:47','2026-08-17 19:00:37','2026-08-05 04:17:33','2026-08-17 19:00:37');
INSERT IGNORE INTO `gov24_public_service` (`service_id`, `support_type`, `service_name`, `service_purpose_summary`, `support_target`, `selection_criteria`, `support_content`, `application_method`, `application_deadline`, `detail_url`, `organization_code`, `organization_name`, `department_name`, `view_count`, `organization_type`, `user_type`, `service_category`, `reception_agency`, `contact_phone`, `source_registered_at`, `source_updated_at`, `synced_at`, `created_at`, `updated_at`) VALUES ('319000000136','현금','유실·유기동물 입양비 지원','동작구 지정 동물보호센터에서 유기동물을 반려의 목적으로 입양한 자에게 입양비 지원','동작구 지정 동물보호센터에서 공고한 유실·유기동물을 반려의 목적으로 입양하려는 자로서 아래의 요건을 모두 충족한 자\r\n   - 동물등록(내장형) 완료\r\n   - 동물사랑배움터(apms.epis.or.kr) 입양예정자 교육 수료자\r\n\r\n  * 입양비 신청자와 입양자가 동일인이어야 함\r\n  * 유기동물 입양일로부터 1년 이내 신청한 건에 한하여 지급',NULL,'ㅇ지원대상: 동작구 지정 동물보호센터*의 유실·유기동물을 반려의 목적으로 입양한 자로서 아래의 요건을 모두 충족하는 자\r\n    - 동물등록(내장형) 완료\r\n    - 동물사랑배움터(apms.epis.or.kr)에서 입양예정자 교육 수료자\r\n\r\n    * 동작구 지정 동물보호센터 : 디아크동물종합병원(동작구 장승배기로27길 18)\r\n\r\nㅇ지원내용: 유실·유기동물을 반려 목적으로 입양 후 소요된 소유자 부담 비용 일부 지원\r\n    - 지원금액 : 입양동물 1마리당 최대 25만원 이내\r\n    - 지원항목 : 질병진단비, 치료비, 예방접종비, 중성화수술비, 내장형 동물등록비, 미용비, 펫보험* 가입비\r\n\r\n    * 펫보험의 경우 신청일 기준 유효한 보험인 경우에 한하여 지원\r\n\r\nㅇ기타\r\n  - 유기동물 입양 후 1년 이내 신청한 건에 한하여 지급\r\n  - 예산 소진 시 마감\r\n  - 선착순 지급','정부24온라인신청||직접입력','유실·유기동물 입양 후 1년 이내 신청한 건에 한하여 지급','https://www.gov.kr/portal/rcvfvrSvc/dtlEx/319000000136','3190000','서울특별시 동작구','감염병관리과',1599,'시군구','개인','보호·돌봄',NULL,'감염병관리과/02-820-9558','2022-07-12 10:34:29','2026-08-03 14:07:23','2026-08-17 19:00:37','2026-08-05 04:17:33','2026-08-17 19:00:37');
INSERT IGNORE INTO `gov24_public_service` (`service_id`, `support_type`, `service_name`, `service_purpose_summary`, `support_target`, `selection_criteria`, `support_content`, `application_method`, `application_deadline`, `detail_url`, `organization_code`, `organization_name`, `department_name`, `view_count`, `organization_type`, `user_type`, `service_category`, `reception_agency`, `contact_phone`, `source_registered_at`, `source_updated_at`, `synced_at`, `created_at`, `updated_at`) VALUES ('320000000313','현금','유기동물 입양비 지원','입양동물 1마리당 최대 25만원 이내 지원','-지원대상: 관악구 지정 유기동물 보호센터에서 유기동물을 반려의 목적으로 입양하여 동물등록(내장형)을 완료한 자',NULL,'-지원비용: 입양동물 1마리당 최대 25만원 이내(자부담 10만원 포함)\r\n  (2025.12.31.까지 입양: 최대 15만원 지원, 2026.1.1.이후 입양: 최대 25만원 지원)\r\n\r\n-지원항목: 질병진단비, 치료비, 예방접종비, 중성화수술비, 내장형 동물등록비, 미용비, 펫보험* 가입비, 사회화 교육 및 훈련비\r\n\r\n*펫보험의 경우 신청일 기준 유효한 보험인 경우에 한하여 지원','정부24온라인신청||방문신청||직접입력','상시신청','https://www.gov.kr/portal/rcvfvrSvc/dtlEx/320000000313','3200000','서울특별시 관악구','일자리벤처과',165,'시군구','개인','생활안정',NULL,'일자리벤처과/02-879-6694','2026-05-07 10:33:43','2026-08-11 16:05:02','2026-08-17 19:00:37','2026-08-05 04:17:33','2026-08-17 19:00:37');
INSERT IGNORE INTO `gov24_public_service` (`service_id`, `support_type`, `service_name`, `service_purpose_summary`, `support_target`, `selection_criteria`, `support_content`, `application_method`, `application_deadline`, `detail_url`, `organization_code`, `organization_name`, `department_name`, `view_count`, `organization_type`, `user_type`, `service_category`, `reception_agency`, `contact_phone`, `source_registered_at`, `source_updated_at`, `synced_at`, `created_at`, `updated_at`) VALUES ('338000000427','현금','사회적약자 반려동물 진료비, 장례비 지원사업','사회적약자 반려동물 진료비·장례비 지원','동물등록(내장형, 외장형)을 완료한 반려동물을 양육하고 있는 수영구 거주 중인 사회적약자',NULL,'- 진료비 : 예방접종 등 진료행위와 수술 등 질병 치료에 소요된 비용의 75% 지원(최대 15만원)\r\n- 장례비 : 허가받은 동물장묘업체 이용 장례비 최대 20만원 이내 지원','방문신청','상시신청','https://www.gov.kr/portal/rcvfvrSvc/dtlEx/338000000427','3380000','부산광역시 수영구','일자리경제과',175,'시군구','개인','생활안정',NULL,'수영구청 일자리경제과/051-610-4501','2025-12-29 17:56:21','2026-07-29 21:07:03','2026-08-17 19:00:36','2026-08-05 04:17:30','2026-08-17 19:00:36');
INSERT IGNORE INTO `gov24_public_service` (`service_id`, `support_type`, `service_name`, `service_purpose_summary`, `support_target`, `selection_criteria`, `support_content`, `application_method`, `application_deadline`, `detail_url`, `organization_code`, `organization_name`, `department_name`, `view_count`, `organization_type`, `user_type`, `service_category`, `reception_agency`, `contact_phone`, `source_registered_at`, `source_updated_at`, `synced_at`, `created_at`, `updated_at`) VALUES ('374000000596','서비스(의료)','(수원시) 사회적 약자 반려동물 진료비 등 지원','수원시 관내 반려동물을 양육하는 사회적 취약가구에게 반려동물 의료·돌봄위탁·장례 비용 지원','수원시에 주민등록을 두고 실제 거주하며 본인 소유로 동물등록 완료된 개, 고양이를 기르는 사회적 취약가구\r\n - 차상위계층 \r\n - 기초생활 수급자\r\n -  장애인 등',NULL,'○ 지원대상 : 수원시에 주민등록을 두고 실제 거주하며 본인 소유로 동물등록 완료된 개, 고양이를 기르는 사회적 취약가구\r\n○ 사업기간 : 3월~11월(사업비 소진시 조기 종료)\r\n○ 사업내용\r\n - 의료지원 : 백신접종비, 중성화수술비, 기본검진 및 치료비 등\r\n - 돌봄지원 : 반려동물 돌봄 위탁비\r\n - 장례지원 : 반려동물 장례, 화장비 등\r\n - 노령동물 종합검진 지원: 만 7세 이상 노령동물 건강검진 비용 등\r\n○ 지원금액(인당 2마리까지)\r\n - 의료,돌봄,장례: 마리당 최대 16만원\r\n - 노령동물 종합검진: 마리당 최대 32만원','방문신청','상시신청','https://www.gov.kr/portal/rcvfvrSvc/dtlEx/374000000596','3740000','경기도 수원시','반려동물센터',314,'시군구','개인','생활안정',NULL,'반려동물센터/031-5191-3458','2025-12-24 12:04:00','2026-08-12 15:32:14','2026-08-17 19:00:36','2026-08-05 04:17:30','2026-08-17 19:00:36');
INSERT IGNORE INTO `gov24_public_service` (`service_id`, `support_type`, `service_name`, `service_purpose_summary`, `support_target`, `selection_criteria`, `support_content`, `application_method`, `application_deadline`, `detail_url`, `organization_code`, `organization_name`, `department_name`, `view_count`, `organization_type`, `user_type`, `service_category`, `reception_agency`, `contact_phone`, `source_registered_at`, `source_updated_at`, `synced_at`, `created_at`, `updated_at`) VALUES ('383000000146','현금','돌봄 취약가구 반려동물 의료서비스 등 지원','취약가구 대상 반려동물 돌봄, 치료비, 장례비 지원','○ 안양시 돌봄 취약가구\r\n - (공통사항) 중위소득 120% 미만 사회적 배려계층 우선지원\r\n - 저소득층, 중증장애인, 한부모가정, 다문화가정, 1인가구',NULL,'< 돌봄 취약가구 반려동물 의료서비스 등 지원>\r\n○ 지원금액: 마리당 최대 20만원(본인부담금 20%포함)\r\n○ 지원내용\r\n - (의료지원) 백신접종비, 중성화수술비, 기본검진 및 치료비(수술 포함) 등\r\n   ※ 동물등록이 된 반려동물에 한하며, 내장형 마이크로칩 반려동물 우선 지원\r\n   ※ 미등록 동물은 동물등록 우선 완료 후 서비스 지원\r\n - (돌봄지원) 돌봄위탁비(최대 10일)\r\n - (장례지원) 장례, 화장비\r\n\r\n< 돌봄 취약가구 반려동물 미용비 지원>\r\n○ 지원금액: 마리당 최대 10만원(본인부담금 20%포함)\r\n○ 지원내용: 미용비(위생케어, 목욕 포함)','방문신청','상시신청','https://www.gov.kr/portal/rcvfvrSvc/dtlEx/383000000146','3830000','경기도 안양시','위생정책과',1893,'시군구','개인','농림축산어업',NULL,'안양시 위생정책과/031-8045-2249','2021-11-01 17:04:13','2026-08-14 13:32:07','2026-08-17 19:00:36','2026-08-05 04:17:31','2026-08-17 19:00:36');
INSERT IGNORE INTO `gov24_public_service` (`service_id`, `support_type`, `service_name`, `service_purpose_summary`, `support_target`, `selection_criteria`, `support_content`, `application_method`, `application_deadline`, `detail_url`, `organization_code`, `organization_name`, `department_name`, `view_count`, `organization_type`, `user_type`, `service_category`, `reception_agency`, `contact_phone`, `source_registered_at`, `source_updated_at`, `synced_at`, `created_at`, `updated_at`) VALUES ('406000000520','현금','돌봄 취약가구 반려동물 의료서비스 등 지원','사회경제적 취약가구에 동물 의료비 및 위탁관리 서비스를 지원','□ 파주시에 주민등록을 두고 반려동물을 양육하는 돌봄 취약가구\r\n  ○ 저소득층 :생계,주거,의료,교육급여 대상자 또는 차상위 계층\r\n  ○ 중증장애인,한부모가구,다문화가구\r\n  ○ 1인가구\r\n     ＊ 동물등록이 된 반려동물에 한하며, 내장형 마이크로칩으로 등록이 된 반려동물 우선지원.\r\n     ＊ 동물등록 여부 확인, 미등록 동물은 先 동물등록조치(내장형)',NULL,'최대 20만원 지원, 초과비용은 자부담\r\n○ 의료지원\r\n  -백신접종비, 중성화수술비, 검진·치료비, 내장형 등록비 등\r\n○돌봄지원 \r\n -반려동물 돌봄 위탁비(최대 10일)\r\n○장례지원\r\n - 반려동물 장례, 화장비 일부 지원(관내업체 이용)','정부24온라인신청||방문신청','매년 초 신청','https://www.gov.kr/portal/rcvfvrSvc/dtlEx/406000000520','4060000','경기도 파주시','동물관리과',140,'시군구','개인||가구','농림축산어업',NULL,'031-940-2910/031-940-2910','2025-11-24 08:52:09','2026-08-12 15:32:34','2026-08-17 19:00:36','2026-08-05 04:17:31','2026-08-17 19:00:36');
