INSERT IGNORE INTO `gov24_public_service` (`service_id`, `support_type`, `service_name`, `service_purpose_summary`, `support_target`, `selection_criteria`, `support_content`, `application_method`, `application_deadline`, `detail_url`, `organization_code`, `organization_name`, `department_name`, `view_count`, `organization_type`, `user_type`, `service_category`, `reception_agency`, `contact_phone`, `source_registered_at`, `source_updated_at`, `synced_at`, `created_at`, `updated_at`) VALUES ('641000000117','기타','동물등록제비용지원','등록대상동물에 대한 내장형 무선식별장치 등록비용 지원','○ 등록대상동물(개, 고양이)',NULL,'○ 등록대상동물에 대한 내장칩 동물등록 비용 지원 (선착순 지원)\r\n - 지원내용 : 경기도 내 등록대상동물에 대한 내장형 무선식별장치 등록비용 지원\r\n - 지원대상 : 경기도민이 소유한 ① 2개월령 이상 된 개, ② 고양이\r\n - 안내사항 : 동물등록 관련 진료상담 비용(1만원 이하) 청구','방문신청','접수기관 별 상이','https://www.gov.kr/portal/rcvfvrSvc/dtlEx/641000000117','6410000','경기도','동물복지과',3962,'광역시도','개인','보호·돌봄',NULL,'수원시/031-5191-3458||고양시/031-8075-4604||용인시/031-6193-3465||성남시/031-729-3296||부천시/032-625-2808||화성시/031-5189-7099||안산시/031-481-2352||남양주시/031-590-3991||안양시/031-8045-2249||평택시/031-8024-3806||시흥시/031-310-2247||파주시/031-940-2910||의정부시/031-828-4082||김포시/031-980-5564||광주시/031-760-4418||광명시/02-2680-6106||군포시/031-390-0783||하남시/031-5182-1165||오산시/031-8036-7643||양주시/031-8082-7362||이천시/031-6190-7391||구리시/031-550-8826||안성시/031-678-5494||포천시/031-538-3882||의왕시/031-345-2385||양평군/031-770-3625||여주시/031-887-3202||동두천시/031-860-2322||가평군/031-580-4788||과천시/02-3677-2346||연천군/031-839-2326','2021-09-23 12:34:56','2026-08-13 08:38:33','2026-08-17 19:00:37','2026-08-05 04:17:33','2026-08-17 19:00:37');
INSERT IGNORE INTO `gov24_public_service` (`service_id`, `support_type`, `service_name`, `service_purpose_summary`, `support_target`, `selection_criteria`, `support_content`, `application_method`, `application_deadline`, `detail_url`, `organization_code`, `organization_name`, `department_name`, `view_count`, `organization_type`, `user_type`, `service_category`, `reception_agency`, `contact_phone`, `source_registered_at`, `source_updated_at`, `synced_at`, `created_at`, `updated_at`) VALUES ('643000000730','서비스(의료)','충청북도 취약계층 반려동물 의료비 지원','반려동물을 기르는 취약계층(사회적약자)의 동물진료비 지원','1. 사업대상자\r\n  ○ 해당 시.군에 주민등록을 둔 취약계층* 중에서 반려동물을 기르는자\r\n\r\n\r\n< *세부 사업대상자 >\r\n\r\n① 국민기초생활수급자 : 「국민기초생활보장법」제7조 제1항 제1호부터 제4호까지의 규정에 따른 수급자(생계, 의료, 주거, 교육) 가구\r\n② 차상위계층 : 「국민기초생활 보장법」제2조 제10호에 따른 차상위계층* 가구\r\n  * 차상위계층은 「국민기초생활 보장법 시행령」 제3조에 따른 소득인 정액이 기준 중위소득의 100분의 50이하인 사람 중 기초생활수급자가 아닌 사람\r\n③ 한부모가족 : 「한부모가족지원법」제5조에 따른 한부모가족* 가구\r\n  * 한부모가족은 「한부모가족지원법 시행규칙」 제3조에 따라 한부모가족증명서 발급대상(소득인정액이 기준 중위소득 63% 이하인 가족\r\n④ 중증장애인 : 「장애인고용법」제2조 제2호에 따른 중증장애인* 가구\r\n  * 중증장애인은 「장애인고용법 시행령」 제4조에 1항에 따른 기준에 해당되는 사람',NULL,'○ 동물의료비 지원 서비스\r\n\r\n1. 지원방법: 동물진료, 수술에 소요되는 비용 지원 \r\n2. 지원한도액: 마리당 200,000원 (자부담 4만원)','방문신청','상시신청','https://www.gov.kr/portal/rcvfvrSvc/dtlEx/643000000730','6430000','충청북도','축수산과',1108,'광역시도','개인','생활안정',NULL,'충청북도 축수산과 동물복지팀/043-220-3733','2025-01-23 16:35:44','2026-08-13 10:02:24','2026-08-17 19:00:37','2026-08-05 04:17:32','2026-08-17 19:00:37');
INSERT IGNORE INTO `gov24_public_service` (`service_id`, `support_type`, `service_name`, `service_purpose_summary`, `support_target`, `selection_criteria`, `support_content`, `application_method`, `application_deadline`, `detail_url`, `organization_code`, `organization_name`, `department_name`, `view_count`, `organization_type`, `user_type`, `service_category`, `reception_agency`, `contact_phone`, `source_registered_at`, `source_updated_at`, `synced_at`, `created_at`, `updated_at`) VALUES ('648000001144','현금','유기동물 입양장려금 지원','시군 동물보호센터의 보호동물 입양 시 입양장려금 제공','도내 시군 동물보호센터에서 유기유실동물*을 반려목적으로 입양하려는 도민으로 동물등록*(내장형)을 완료한 입양자\r\n* 동물보호법 제20조에 따라 지자체장이 소유권을 취득한 동물\r\n** 동물보호법 시행령 제6조에 따른 비영리법인 단체가 동물보호센터로부터 기증받은 동물을 개인에게 분양한 경우, 입양자가 동물등록 후 신청가능(동물보호 법인·단체는 지원대상 아님',NULL,'도내 시군 동물보호센터의 보호동물(유기·유실동물)을 반려의 목적으로 입양하려는 자로서\r\n동물등록(내장형 인식)을 완료한 입양자를 대상으로 입양장려금 제공','방문신청','입양 후 6개월 이내(시군별 사업량 소진 시까지)','https://www.gov.kr/portal/rcvfvrSvc/dtlEx/648000001144','6480000','경상남도','축산과',256,'광역시도','개인','농림축산어업',NULL,'경상남도 축산과/055-211-6543','2025-07-07 20:41:04','2026-08-12 15:23:13','2026-08-17 19:00:37','2026-08-05 04:17:33','2026-08-17 19:00:37');
INSERT IGNORE INTO `gov24_public_service` (`service_id`, `support_type`, `service_name`, `service_purpose_summary`, `support_target`, `selection_criteria`, `support_content`, `application_method`, `application_deadline`, `detail_url`, `organization_code`, `organization_name`, `department_name`, `view_count`, `organization_type`, `user_type`, `service_category`, `reception_agency`, `contact_phone`, `source_registered_at`, `source_updated_at`, `synced_at`, `created_at`, `updated_at`) VALUES ('648000001145','현금','입양동물 펫보험 가입 지원','시군 동물보호센터의 보호동물 입양 시, 입양동물 펫보험 가입비 지원','도내 시군 동물보호센터에서 유기유실동물*을 반려목적으로 입양하려는 도민으로 동물등록*(내장형)을 완료한 입양자\r\n - 단, 동물등록 미확인 시, 지원 불가\r\n* 동물보호법 제20조에 따라 지자체장이 소유권을 취득한 동물\r\n** 동물보호법 시행령 제6조에 따른 비영리법인 단체가 동물보호센터로부터 기증받은 동물을 개인에게 분양한 경우, 입양자가 동물등록 후 신청가능(동물보호 법인·단체는 지원대상 아님',NULL,'도내 시군 동물보호센터의 보호동물(유기·유실동물)을 반려의 목적으로 입양하려는 자로서\r\n동물등록(내장형 인식)을 완료하고 펫보험에 가입한 입양자를 대상으로 펫보험 가입비용 지원','방문신청','입양 후 6개월 이내(시군별 사업량 소진 시까지)','https://www.gov.kr/portal/rcvfvrSvc/dtlEx/648000001145','6480000','경상남도','축산과',253,'광역시도','개인','농림축산어업',NULL,'경상남도 축산과/055-211-6543','2025-07-07 21:14:41','2026-08-12 15:20:37','2026-08-17 19:00:37','2026-08-05 04:17:34','2026-08-17 19:00:37');
