INSERT IGNORE INTO `local_support_program` (`source_service_id`, `source_type`, `region`, `program_name`, `description`, `summary`, `agency_name`, `benefit_summary`, `eligibility`, `target_species`, `apply_url`, `period_text`, `application_method`, `start_date`, `end_date`, `is_active`, `source_updated_at`, `synced_at`, `created_at`, `updated_at`) VALUES ('seed-gov-pet-001','GOV24','서울특별시','서울시 반려동물 중성화 지원','중성화 수술비를 지원합니다.','조건 충족 시 최대 15만원','서울특별시 동물복지과','최대 150,000원','{\"test\": true}','DOG','https://example.test/support/1','2026년 12월 31일까지','온라인 신청','2026-07-05','2027-01-31',0,NULL,'2026-08-04 07:17:36','2026-08-04 07:17:36','2026-08-05 04:17:30');
INSERT IGNORE INTO `local_support_program` (`source_service_id`, `source_type`, `region`, `program_name`, `description`, `summary`, `agency_name`, `benefit_summary`, `eligibility`, `target_species`, `apply_url`, `period_text`, `application_method`, `start_date`, `end_date`, `is_active`, `source_updated_at`, `synced_at`, `created_at`, `updated_at`) VALUES ('seed-gov-pet-002','GOV24','제주특별자치도','제주 유기동물 입양비 지원','입양 초기 비용을 지원합니다.','입양 후 6개월 이내 신청','제주특별자치도 동물복지과','최대 200,000원','{\"test\": true}','ALL','https://example.test/support/2','예산 소진 시까지','온라인 또는 방문','2026-07-05',NULL,0,NULL,'2026-08-04 07:17:36','2026-08-04 07:17:36','2026-08-05 04:17:30');
INSERT IGNORE INTO `local_support_program` (`source_service_id`, `source_type`, `region`, `program_name`, `description`, `summary`, `agency_name`, `benefit_summary`, `eligibility`, `target_species`, `apply_url`, `period_text`, `application_method`, `start_date`, `end_date`, `is_active`, `source_updated_at`, `synced_at`, `created_at`, `updated_at`) VALUES ('305000000130','GOV24','서울특별시','취약계층 반려동물 의료비 지원','지원대상 : 관내 주민등록을 두고 개와 고양이를 기르는 기초생활수급자, 차상위계층 및 한부모가족(가구당 2마리까지 신청 가능)\r\n\r\n사업기간 : ~ 예산소진시까지\r\n\r\n신청방법 : 동물등록자 본인이 반려동물과 함께 준비서류를 준비하여 관내 지정 동물병원에 방문하여 신청\r\n *준비서류 : 신분증, 취약계층 증빙서류(수급자 증명서, 차상위계층, 한부모가족 확인서)-3개월이내 발급/ 반려견,반려묘의 경우 동물등록증\r\n\r\n\r\n\r\n지원내용\r\n \r\n 1. 필수진료 : 반려동물 필수 동물의료지원(정해진 진료 항목만 지원가능)\r\n   - 기초건강검진, 필수예방접종, 심장사상충 예방약\r\n   - 마리당 20만원 이내 지원, 보호자 1만원 부담\r\n 2. 선택진료 : 필수진료 후 추가 진료 요청시 지원\r\n   - 기초검진과정 중 발견된 증상, 질병에 대해 치료 또는 중성화 수술\r\n   - 진료 후 치료가 필요한 진료 항목만을 지원하며, 미용, 심장사상충 예방약, 영양제 등 단순 처방은 제외\r\n   - 마리당 20만원 이내 지원(초과하는 진료비는 보호자 부담)','관내 수급자, 차상위계층, 한부모가족 반려동물 의료비 지원','서울특별시 동대문구','서비스(의료)',NULL,'ALL','https://www.gov.kr/portal/rcvfvrSvc/dtlEx/305000000130','~예산소진시까지','방문신청',NULL,NULL,1,'2026-08-14 09:49:07','2026-08-17 19:00:36','2026-08-05 04:17:30','2026-08-17 19:00:36');
INSERT IGNORE INTO `local_support_program` (`source_service_id`, `source_type`, `region`, `program_name`, `description`, `summary`, `agency_name`, `benefit_summary`, `eligibility`, `target_species`, `apply_url`, `period_text`, `application_method`, `start_date`, `end_date`, `is_active`, `source_updated_at`, `synced_at`, `created_at`, `updated_at`) VALUES ('305000000167','GOV24','서울특별시','반려동물 전문인력 양성사업','반려동물 관련 취업을 희망하는 구민에게 취업 전문 교육 및 취업연계','반려동물 관련 취업을 희망하는 구민에게 취업 전문 교육 및 취업연계','서울특별시 동대문구','기타(교육)||서비스(일자리)',NULL,'ALL','https://www.ddm.go.kr/www/index.do','2025.08.06~2025.09.05','정부24온라인신청||기타 온라인신청',NULL,NULL,1,'2026-08-14 09:44:54','2026-08-17 19:00:36','2026-08-05 04:17:30','2026-08-17 19:00:36');
