INSERT IGNORE INTO `local_support_program` (`source_service_id`, `source_type`, `region`, `program_name`, `description`, `summary`, `agency_name`, `benefit_summary`, `eligibility`, `target_species`, `apply_url`, `period_text`, `application_method`, `start_date`, `end_date`, `is_active`, `source_updated_at`, `synced_at`, `created_at`, `updated_at`) VALUES ('338000000427','GOV24','부산광역시','사회적약자 반려동물 진료비, 장례비 지원사업','- 진료비 : 예방접종 등 진료행위와 수술 등 질병 치료에 소요된 비용의 75% 지원(최대 15만원)\r\n- 장례비 : 허가받은 동물장묘업체 이용 장례비 최대 20만원 이내 지원','사회적약자 반려동물 진료비·장례비 지원','부산광역시 수영구','현금',NULL,'ALL','https://www.gov.kr/portal/rcvfvrSvc/dtlEx/338000000427','상시신청','방문신청',NULL,NULL,1,'2026-07-29 21:07:03','2026-08-17 19:00:36','2026-08-05 04:17:30','2026-08-17 19:00:36');
INSERT IGNORE INTO `local_support_program` (`source_service_id`, `source_type`, `region`, `program_name`, `description`, `summary`, `agency_name`, `benefit_summary`, `eligibility`, `target_species`, `apply_url`, `period_text`, `application_method`, `start_date`, `end_date`, `is_active`, `source_updated_at`, `synced_at`, `created_at`, `updated_at`) VALUES ('374000000596','GOV24','경기도','(수원시) 사회적 약자 반려동물 진료비 등 지원','○ 지원대상 : 수원시에 주민등록을 두고 실제 거주하며 본인 소유로 동물등록 완료된 개, 고양이를 기르는 사회적 취약가구\r\n○ 사업기간 : 3월~11월(사업비 소진시 조기 종료)\r\n○ 사업내용\r\n - 의료지원 : 백신접종비, 중성화수술비, 기본검진 및 치료비 등\r\n - 돌봄지원 : 반려동물 돌봄 위탁비\r\n - 장례지원 : 반려동물 장례, 화장비 등\r\n - 노령동물 종합검진 지원: 만 7세 이상 노령동물 건강검진 비용 등\r\n○ 지원금액(인당 2마리까지)\r\n - 의료,돌봄,장례: 마리당 최대 16만원\r\n - 노령동물 종합검진: 마리당 최대 32만원','수원시 관내 반려동물을 양육하는 사회적 취약가구에게 반려동물 의료·돌봄위탁·장례 비용 지원','경기도 수원시','서비스(의료)',NULL,'ALL','https://www.gov.kr/portal/rcvfvrSvc/dtlEx/374000000596','상시신청','방문신청',NULL,NULL,1,'2026-08-12 15:32:14','2026-08-17 19:00:36','2026-08-05 04:17:31','2026-08-17 19:00:36');
INSERT IGNORE INTO `local_support_program` (`source_service_id`, `source_type`, `region`, `program_name`, `description`, `summary`, `agency_name`, `benefit_summary`, `eligibility`, `target_species`, `apply_url`, `period_text`, `application_method`, `start_date`, `end_date`, `is_active`, `source_updated_at`, `synced_at`, `created_at`, `updated_at`) VALUES ('383000000146','GOV24','경기도','돌봄 취약가구 반려동물 의료서비스 등 지원','< 돌봄 취약가구 반려동물 의료서비스 등 지원>\r\n○ 지원금액: 마리당 최대 20만원(본인부담금 20%포함)\r\n○ 지원내용\r\n - (의료지원) 백신접종비, 중성화수술비, 기본검진 및 치료비(수술 포함) 등\r\n   ※ 동물등록이 된 반려동물에 한하며, 내장형 마이크로칩 반려동물 우선 지원\r\n   ※ 미등록 동물은 동물등록 우선 완료 후 서비스 지원\r\n - (돌봄지원) 돌봄위탁비(최대 10일)\r\n - (장례지원) 장례, 화장비\r\n\r\n< 돌봄 취약가구 반려동물 미용비 지원>\r\n○ 지원금액: 마리당 최대 10만원(본인부담금 20%포함)\r\n○ 지원내용: 미용비(위생케어, 목욕 포함)','취약가구 대상 반려동물 돌봄, 치료비, 장례비 지원','경기도 안양시','현금',NULL,'ALL','https://www.gov.kr/portal/rcvfvrSvc/dtlEx/383000000146','상시신청','방문신청',NULL,NULL,1,'2026-08-14 13:32:07','2026-08-17 19:00:36','2026-08-05 04:17:31','2026-08-17 19:00:36');
