INSERT IGNORE INTO `local_support_program` (`source_service_id`, `source_type`, `region`, `program_name`, `description`, `summary`, `agency_name`, `benefit_summary`, `eligibility`, `target_species`, `apply_url`, `period_text`, `application_method`, `start_date`, `end_date`, `is_active`, `source_updated_at`, `synced_at`, `created_at`, `updated_at`) VALUES ('554000000163','GOV24','경기도','돌봄 취약가구 반려동물 의료서비스 등 지원','○ 지원금액: 마리당 최대 20만원(본인부담금 20%(4만원) 포함)\r\n○ 지원내용\r\n - (의료지원) 백신접종비, 중성화수술비, 기본검진 및 치료비(수술 포함) 등\r\n - (돌봄지원) 반려동물 돌봄위탁비(최대 10일이내)','- (의료지원) 백신접종비, 중성화수술비, 기본검진 및 치료비(수술 포함) 등','경기도 광주시','현금',NULL,'ALL','https://www.gov.kr/portal/rcvfvrSvc/dtlEx/554000000163','상시신청','방문신청',NULL,NULL,1,'2026-05-12 15:22:40','2026-08-17 19:00:37','2026-08-05 04:17:32','2026-08-17 19:00:37');
INSERT IGNORE INTO `local_support_program` (`source_service_id`, `source_type`, `region`, `program_name`, `description`, `summary`, `agency_name`, `benefit_summary`, `eligibility`, `target_species`, `apply_url`, `period_text`, `application_method`, `start_date`, `end_date`, `is_active`, `source_updated_at`, `synced_at`, `created_at`, `updated_at`) VALUES ('626000000139','GOV24','부산광역시','사회적약자 반려동물 진료비 지원','○중증장애인, 수급자, 차상위 계층에 대한 반려동물 진료비 지원(20만원 이내)으로 반려동물 적정 보호 기여','반려동물을 키우는 사회적약자에게 동물진료비 지원','부산광역시','현금',NULL,'ALL','https://www.gov.kr/portal/rcvfvrSvc/dtlEx/626000000139','상시신청','방문신청',NULL,NULL,1,'2026-07-27 14:11:48','2026-08-17 19:00:37','2026-08-05 04:17:32','2026-08-17 19:00:37');
INSERT IGNORE INTO `local_support_program` (`source_service_id`, `source_type`, `region`, `program_name`, `description`, `summary`, `agency_name`, `benefit_summary`, `eligibility`, `target_species`, `apply_url`, `period_text`, `application_method`, `start_date`, `end_date`, `is_active`, `source_updated_at`, `synced_at`, `created_at`, `updated_at`) VALUES ('629000000117','GOV24','전남광주통합특별시','반려동물 내장형 동물등록 지원','○ 지원내용 : 반려동물(반려견,반려묘)의 내장형 동물등록을 유도하여 유기동물 발생을 최소화하기 위해 반려동물(반려견,반려묘) 내장형 동물등록시 비용 일부를 지원\r\n\r\n○ 지원금 : 1마리당 최대 4만원\r\n\r\n○ 사업량 : 2,775두\r\n\r\n ※ 사업량 소진시 지원 불가','반려동물(반려견,반려묘) 소유자에게 내장형 동물등록칩 비용 지원','전남광주통합특별시','현금',NULL,'ALL','https://www.gov.kr/portal/rcvfvrSvc/dtlEx/629000000117','상시신청','방문신청',NULL,NULL,1,'2026-08-14 15:03:41','2026-08-17 19:00:37','2026-08-05 04:17:32','2026-08-17 19:00:37');
INSERT IGNORE INTO `local_support_program` (`source_service_id`, `source_type`, `region`, `program_name`, `description`, `summary`, `agency_name`, `benefit_summary`, `eligibility`, `target_species`, `apply_url`, `period_text`, `application_method`, `start_date`, `end_date`, `is_active`, `source_updated_at`, `synced_at`, `created_at`, `updated_at`) VALUES ('643000000730','GOV24','충청북도','충청북도 취약계층 반려동물 의료비 지원','○ 동물의료비 지원 서비스\r\n\r\n1. 지원방법: 동물진료, 수술에 소요되는 비용 지원 \r\n2. 지원한도액: 마리당 200,000원 (자부담 4만원)','반려동물을 기르는 취약계층(사회적약자)의 동물진료비 지원','충청북도','서비스(의료)',NULL,'ALL','https://www.gov.kr/portal/rcvfvrSvc/dtlEx/643000000730','상시신청','방문신청',NULL,NULL,1,'2026-08-13 10:02:24','2026-08-17 19:00:37','2026-08-05 04:17:32','2026-08-17 19:00:37');
INSERT IGNORE INTO `local_support_program` (`source_service_id`, `source_type`, `region`, `program_name`, `description`, `summary`, `agency_name`, `benefit_summary`, `eligibility`, `target_species`, `apply_url`, `period_text`, `application_method`, `start_date`, `end_date`, `is_active`, `source_updated_at`, `synced_at`, `created_at`, `updated_at`) VALUES ('305000000132','GOV24','서울특별시','동대문구 유기동물 입양비 지원','1. 지원대상 : 우리 구 보호중인 유기동물을 반려 목적으로 입양하려는 자로써 동물등록 완료 입양자\r\n  - 유기돔물 입양 후 6개월 이내 신청 건에 한하여 지급\r\n2. 신청방법 : 입양자 본인이 유기동물 입양관련 비용 지출 후 서류 준비하여 신청(방문, 이메일) 검토 후 지급\r\n  - 준비서류 : 입양비 신청서, 입양자 신분증, 입양확인서 사본, 등물등록증 사본, 입양비 지출 관련 증빙서류(지출영수증, 병원진료내역서, 기타 입양관련 지출내역 등)\r\n                      입양자 본인명의 통장사본\r\n3. 지원내용 : 질병질단비, 치료비, 예방접종, 중성화수술비, 내장형 동물 등록비, 미용비, 펫보험 가입비(신청일 기준 유효한 것) \r\n                      중 입양 시 지출한 비용 중 마리당 최대     25     만원까지 지원','관내 유실,유기동물을 반려 목적의 입양 후 소요된 소유자 부담 비용 지원/1마리당 25만원','서울특별시 동대문구','현금',NULL,'ALL','https://www.gov.kr/portal/rcvfvrSvc/dtlEx/305000000132','상시신청','방문신청',NULL,NULL,1,'2026-08-14 09:47:23','2026-08-17 19:00:37','2026-08-05 04:17:33','2026-08-17 19:00:37');
INSERT IGNORE INTO `local_support_program` (`source_service_id`, `source_type`, `region`, `program_name`, `description`, `summary`, `agency_name`, `benefit_summary`, `eligibility`, `target_species`, `apply_url`, `period_text`, `application_method`, `start_date`, `end_date`, `is_active`, `source_updated_at`, `synced_at`, `created_at`, `updated_at`) VALUES ('318000000432','GOV24','서울특별시','유실·유기동물 입양비 지원','영등포구 지정 동물보호센터의 유실·유기동물 입양시 소유자 부담비용 지원\r\n- 소유자 부담비용의 60%, 최대 15만원 지원\r\n- 지원범위: 질병진단비, 치료비, 예방접종, 중성화수술비, 내장형 동물등록비, 미용비, 펫보험 가입비(신청일 기준 유효한 보험에 한함), 사회화교육 및 훈련비','영등포구 지정 동물보호센터의 유실·유기동물 입양시 소유자 부담비용 지원(최대 15만원)','서울특별시 영등포구','현금',NULL,'ALL','https://www.gov.kr/portal/rcvfvrSvc/dtlEx/318000000432','입양 후 1년 이내. 예산 소진시까지','직접입력',NULL,NULL,1,'2026-08-05 14:52:47','2026-08-17 19:00:37','2026-08-05 04:17:33','2026-08-17 19:00:37');
INSERT IGNORE INTO `local_support_program` (`source_service_id`, `source_type`, `region`, `program_name`, `description`, `summary`, `agency_name`, `benefit_summary`, `eligibility`, `target_species`, `apply_url`, `period_text`, `application_method`, `start_date`, `end_date`, `is_active`, `source_updated_at`, `synced_at`, `created_at`, `updated_at`) VALUES ('319000000136','GOV24','서울특별시','유실·유기동물 입양비 지원','ㅇ지원대상: 동작구 지정 동물보호센터*의 유실·유기동물을 반려의 목적으로 입양한 자로서 아래의 요건을 모두 충족하는 자\r\n    - 동물등록(내장형) 완료\r\n    - 동물사랑배움터(apms.epis.or.kr)에서 입양예정자 교육 수료자\r\n\r\n    * 동작구 지정 동물보호센터 : 디아크동물종합병원(동작구 장승배기로27길 18)\r\n\r\nㅇ지원내용: 유실·유기동물을 반려 목적으로 입양 후 소요된 소유자 부담 비용 일부 지원\r\n    - 지원금액 : 입양동물 1마리당 최대 25만원 이내\r\n    - 지원항목 : 질병진단비, 치료비, 예방접종비, 중성화수술비, 내장형 동물등록비, 미용비, 펫보험* 가입비\r\n\r\n    * 펫보험의 경우 신청일 기준 유효한 보험인 경우에 한하여 지원\r\n\r\nㅇ기타\r\n  - 유기동물 입양 후 1년 이내 신청한 건에 한하여 지급\r\n  - 예산 소진 시 마감\r\n  - 선착순 지급','동작구 지정 동물보호센터에서 유기동물을 반려의 목적으로 입양한 자에게 입양비 지원','서울특별시 동작구','현금',NULL,'ALL','https://www.gov.kr/portal/rcvfvrSvc/dtlEx/319000000136','유실·유기동물 입양 후 1년 이내 신청한 건에 한하여 지급','정부24온라인신청||직접입력',NULL,NULL,1,'2026-08-03 14:07:23','2026-08-17 19:00:37','2026-08-05 04:17:33','2026-08-17 19:00:37');
INSERT IGNORE INTO `local_support_program` (`source_service_id`, `source_type`, `region`, `program_name`, `description`, `summary`, `agency_name`, `benefit_summary`, `eligibility`, `target_species`, `apply_url`, `period_text`, `application_method`, `start_date`, `end_date`, `is_active`, `source_updated_at`, `synced_at`, `created_at`, `updated_at`) VALUES ('320000000313','GOV24','서울특별시','유기동물 입양비 지원','-지원비용: 입양동물 1마리당 최대 25만원 이내(자부담 10만원 포함)\r\n  (2025.12.31.까지 입양: 최대 15만원 지원, 2026.1.1.이후 입양: 최대 25만원 지원)\r\n\r\n-지원항목: 질병진단비, 치료비, 예방접종비, 중성화수술비, 내장형 동물등록비, 미용비, 펫보험* 가입비, 사회화 교육 및 훈련비\r\n\r\n*펫보험의 경우 신청일 기준 유효한 보험인 경우에 한하여 지원','입양동물 1마리당 최대 25만원 이내 지원','서울특별시 관악구','현금',NULL,'ALL','https://www.gov.kr/portal/rcvfvrSvc/dtlEx/320000000313','상시신청','정부24온라인신청||방문신청||직접입력',NULL,NULL,1,'2026-08-11 16:05:02','2026-08-17 19:00:37','2026-08-05 04:17:33','2026-08-17 19:00:37');
INSERT IGNORE INTO `local_support_program` (`source_service_id`, `source_type`, `region`, `program_name`, `description`, `summary`, `agency_name`, `benefit_summary`, `eligibility`, `target_species`, `apply_url`, `period_text`, `application_method`, `start_date`, `end_date`, `is_active`, `source_updated_at`, `synced_at`, `created_at`, `updated_at`) VALUES ('648000001144','GOV24','경상남도','유기동물 입양장려금 지원','도내 시군 동물보호센터의 보호동물(유기·유실동물)을 반려의 목적으로 입양하려는 자로서\r\n동물등록(내장형 인식)을 완료한 입양자를 대상으로 입양장려금 제공','시군 동물보호센터의 보호동물 입양 시 입양장려금 제공','경상남도','현금',NULL,'ALL','https://www.gov.kr/portal/rcvfvrSvc/dtlEx/648000001144','입양 후 6개월 이내(시군별 사업량 소진 시까지)','방문신청',NULL,NULL,1,'2026-08-12 15:23:13','2026-08-17 19:00:37','2026-08-05 04:17:33','2026-08-17 19:00:37');
INSERT IGNORE INTO `local_support_program` (`source_service_id`, `source_type`, `region`, `program_name`, `description`, `summary`, `agency_name`, `benefit_summary`, `eligibility`, `target_species`, `apply_url`, `period_text`, `application_method`, `start_date`, `end_date`, `is_active`, `source_updated_at`, `synced_at`, `created_at`, `updated_at`) VALUES ('641000000117','GOV24','경기도','동물등록제비용지원','○ 등록대상동물에 대한 내장칩 동물등록 비용 지원 (선착순 지원)\r\n - 지원내용 : 경기도 내 등록대상동물에 대한 내장형 무선식별장치 등록비용 지원\r\n - 지원대상 : 경기도민이 소유한 ① 2개월령 이상 된 개, ② 고양이\r\n - 안내사항 : 동물등록 관련 진료상담 비용(1만원 이하) 청구','등록대상동물에 대한 내장형 무선식별장치 등록비용 지원','경기도','기타',NULL,'ALL','https://www.gov.kr/portal/rcvfvrSvc/dtlEx/641000000117','접수기관 별 상이','방문신청',NULL,NULL,1,'2026-08-13 08:38:33','2026-08-17 19:00:37','2026-08-05 04:17:34','2026-08-17 19:00:37');
